    sites:sum("sites"),users:u,docs:sum("docs"),rec:sum("rec"),phys:sum("phys"),due:sum("due"),idle180:sum("idle180"),
    visitors:sum("visitors"),views:sum("views"),duephys:sum("duephys"),gb:+sum("gb").toFixed(1),recgb:+sum("recgb").toFixed(1),
